(385,'POST_PASE_ORCHESTRATOR','LF_GOVERNANCE',NULL::timestamptz,'d0ad86bac59729e9cccc51c4fabf30ddd60460c099e5fd0acc71dff77e8fb9df'),
(387,'CONSUMER_BINDINGS','LF_GOVERNANCE',NULL::timestamptz,'09d611814a7d402c9252f2ebe9ff82e0246e2214cb2e68f16baf46f1c4ae2081'),
(388,'PLAN_DELTA_AUTHORITY_READBACK_PRODUCER','LF_GOVERNANCE',NULL::timestamptz,'aa0d971f5c4c7731e321fd9b3d095d815a88235f5f34519b8d94dd0d0307322a'),
(392,'INPUT_READINESS_CONTRACT','LF_GOVERNANCE',NULL::timestamptz,'701b371b4cfe19357b5213750a950699fc62f8676c893e3714d95c2134a7a95a'),
(393,'INPUT_FRESHNESS_DELTA_CONTRACT','LF_GOVERNANCE',NULL::timestamptz,'b1cd5035086e310c8688d94ebd1c3db281943793e0e31718977e58dcb3fef018'),
(394,'INPUT_GOVERNANCE_EXECUTION_CONTRACT','LF_GOVERNANCE',NULL::timestamptz,'26ca2ff134654f65c5cf7bc573f08b72493387d538aed641741cd4fd38b077cd'),
(397,'PROGRAMACION_FN_INPUT_CONTRACT_CLAUSE_V1',NULL,NULL::timestamptz,'fddb41c4c7f4176521c6f0624a4ade9e804b3cb03ec9653b6a8940e73c3fec80'),
(398,'TYPED_DATA_ACCESS','SUPER_ADMIN',NULL::timestamptz,'afe90bebe29244a4f1c904f041a79a3e7d238d8d134843724e0b557e50bc862a'),
(400,'INPUT_GOVERNANCE_PERFORMANCE_ASSURANCE_V1','SUPER_ADMIN',NULL::timestamptz,'944304c695d59bc24e367e05ee30eb55b018f7e510409a99ef38eddbd44764e2'),
(402,'INPUT_GOVERNANCE_COHORT_SELECTION_V1','SUPER_ADMIN',NULL::timestamptz,'f04c1eebf28af33a70fa42887fb89583c4e1042369c27b4a3af3f801503ff9c6'),
(404,'LF_OPS_FN_B2B_BACKOFFICE_LOGIN_CONTRACT','SUPER_ADMIN',NULL::timestamptz,'f84b9431eea89ac9e121ce7ebf20437715ba11114e03dea41669b0065a659817'),
(407,'LF_MIGRATION_MERGE_TRAIN','PENDING_OWNER_CONFIRMATION',NULL::timestamptz,'8bff359e48807b758277a875434546df10520325a9fdffa9eb2ede1863946f34'),
(409,'INPUT_GOVERNANCE_BENCHMARK_CORPUS_V1','INPUT_GOVERNANCE',NULL::timestamptz,'a0c64fa69e4e828bd7fc6425e2f93b9da8b202dce53adbf4530c743f030b3aa0'),
(413,'POL-LF-MIGRATION-NAMING','LF_GOVERNANCE',NULL::timestamptz,'25f7845b2c1f593f765264ae203593d434d282f1ec14747e5a65af0a1b144ec6'),
(414,'PROGRAMMING_ANALYSIS_LF','LF_GOVERNANCE',NULL::timestamptz,'3cf4a281e5e4dd990af11da5d71c98d9a0323d3ddf0facb75e66d6b515a3c272')
 ) t(id,codigo_activo,owner_original,archived_original,sha256_original);
DO $batch$
DECLARE
 e record; a public.lf_activos%ROWTYPE; train public.lf_operation_execution%ROWTYPE;
 cnt int; changes int:=0; active_changes int:=0; archived_changes int:=0;
 sha text; doc jsonb; approval jsonb; effect jsonb;
BEGIN
 IF to_regprocedure('public.lf_ig_asset_owner_approve_v2(text,text,text,text,jsonb)') IS NULL
 OR to_regprocedure('public.lf_ig_asset_owner_approve_archived_v3(text,text,text,text,jsonb)') IS NULL
 OR to_regprocedure('public.lf_ig_asset_owner_apply_v2(uuid)') IS NULL
 OR to_regclass('public.lf_ig_asset_owner_receipt_v2') IS NULL
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_OFFICIAL_WRITER_MISSING'; END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.lf_activos'::regclass
   AND NOT tgisinternal AND tgname IN ('trg_lf_asset_owner_one_name_insert_v1','trg_lf_asset_owner_one_name_update_v1'))<>2
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_GUARD_MISSING'; END IF;
 SELECT count(*) INTO cnt FROM public.lf_operation_execution
 WHERE operation_code='ACTUALIZACION_DB_LF' AND status='IN_PROGRESS'
 AND target_type='MIGRATION' AND target_path ~ '(^|/)[0-9]{14}_lf_asset_owner_one_name_backfill_v1[.]sql$';
 IF cnt<>1 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_UNIQUE_TRAIN_RUN_REQUIRED %',cnt; END IF;
 SELECT * INTO train FROM public.lf_operation_execution
 WHERE operation_code='ACTUALIZACION_DB_LF' AND status='IN_PROGRESS'
 AND target_type='MIGRATION' AND target_path ~ '(^|/)[0-9]{14}_lf_asset_owner_one_name_backfill_v1[.]sql$';
 IF NOT EXISTS(SELECT 1 FROM public.lf_operation_execution_steps
    WHERE execution_id=train.execution_id AND step_id='preflight' AND status='PASS_CLEAN')
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_TRAIN_PREFLIGHT_REQUIRED'; END IF;
 IF nullif(btrim(coalesce(train.manifest->>'proposer_actor','')),'') IS NULL
   OR train.manifest->>'proposer_actor'='Cristhian Luján'
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_DOCUMENTARY_PROPOSER_REQUIRED'; END IF;
 IF (SELECT count(*) FROM public.lf_activos)<>238
 OR (SELECT count(*) FROM pg_temp.lf_owner_batch_preimage_155)<>238
 OR (SELECT count(*) FROM pg_temp.lf_owner_batch_preimage_155
     WHERE owner_original IS DISTINCT FROM 'LF_GOVERNANCE')<>155
 OR (SELECT count(*) FROM pg_temp.lf_owner_batch_preimage_155 WHERE archived_original IS NOT NULL)<>13
 OR (SELECT count(*) FROM pg_temp.lf_owner_batch_preimage_155 WHERE archived_original IS NOT NULL
      AND owner_original IS DISTINCT FROM 'LF_GOVERNANCE')<>11
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_POPULATION_OR_COHORT_DRIFT'; END IF;
 -- Validate/lock EVERY original before the first write.
 FOR e IN SELECT * FROM pg_temp.lf_owner_batch_preimage_155 ORDER BY id LOOP
  SELECT * INTO a FROM public.lf_activos
   WHERE id=e.id AND codigo_activo=e.codigo_activo FOR SHARE;
  IF NOT FOUND OR a.owner_name IS DISTINCT FROM e.owner_original
    OR a.archived_at IS DISTINCT FROM e.archived_original
  THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_ROW_SCOPE_DRIFT id=%',e.id; END IF;
  sha:=encode(extensions.digest(convert_to((to_jsonb(a)-'updated_at')::text,'UTF8'),'sha256'),'hex');
  IF sha IS DISTINCT FROM e.sha256_original
  THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_SHA_DRIFT id=%',e.id; END IF;
 END LOOP;
 -- One documentary decision record PER ROW, all from the same known user
 -- declaration. fecha is the current registration time inside the Train.
 FOR e IN SELECT * FROM pg_temp.lf_owner_batch_preimage_155
   WHERE owner_original IS DISTINCT FROM 'LF_GOVERNANCE' ORDER BY id LOOP
  doc:=jsonb_build_object(
   'codigo_activo',e.codigo_activo,'preimagen_sha256',e.sha256_original,
   'veredicto','APROBAR','decisor','Cristhian Luján',
   'fecha',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD')||'T'||
           to_char(clock_timestamp() at time zone 'UTC','HH24:MI:SS')||'Z',
   'frase_literal','El owner de los activos queda con un solo nombre, LF_GOVERNANCE.');
  IF e.archived_original IS NOT NULL THEN
   approval:=public.lf_ig_asset_owner_approve_archived_v3(
     train.execution_id,e.codigo_activo,e.sha256_original,'LF_GOVERNANCE',doc);
   archived_changes:=archived_changes+1;
  ELSE
   approval:=public.lf_ig_asset_owner_approve_v2(
     train.execution_id,e.codigo_activo,e.sha256_original,'LF_GOVERNANCE',doc);
   active_changes:=active_changes+1;
  END IF;
  IF approval->>'status' IS DISTINCT FROM 'APPROVED'
    OR approval->>'decisor' IS DISTINCT FROM 'Cristhian Luján'
    OR approval->>'identity_verified' IS DISTINCT FROM 'false'
    OR nullif(approval->>'receipt_id','') IS NULL
  THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_DOCUMENTARY_RECEIPT_MISSING %',e.codigo_activo; END IF;
  effect:=public.lf_ig_asset_owner_apply_v2((approval->>'receipt_id')::uuid);
  IF effect->>'status' IS DISTINCT FROM 'APPLIED_VERIFIED'
    OR effect->>'old_sha256' IS DISTINCT FROM e.sha256_original
    OR coalesce(effect->>'new_sha256','') !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_WRITE_READBACK_FAILED %',e.codigo_activo; END IF;
  changes:=changes+1;
 END LOOP;
 IF changes<>155 OR active_changes<>144 OR archived_changes<>11
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_EFFECT_CARDINALITY'; END IF;
 IF (SELECT count(*) FROM public.lf_ig_asset_owner_receipt_v2
     WHERE train_execution_id=train.execution_id AND state='APPLIED'
       AND proposed_owner='LF_GOVERNANCE' AND decisor='Cristhian Luján'
       AND after_sha256 ~ '^[0-9a-f]{64}$'
       AND (before_row->>'owner_name') IS DISTINCT FROM 'LF_GOVERNANCE')<>155
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_155_RECEIPTS_NOT_VERIFIED'; END IF;
 IF (SELECT count(*) FROM public.lf_activos)<>238
 OR (SELECT count(*) FROM public.lf_activos WHERE owner_name='LF_GOVERNANCE')<>238
 OR (SELECT count(*) FROM public.lf_activos WHERE archived_at IS NOT NULL)<>13
 THEN RAISE EXCEPTION 'LF_OWNER_BACKFILL_AFTER_COUNT_MISMATCH'; END IF;
 RAISE NOTICE 'LF_OWNER_BACKFILL_TESTED_155_DOCUMENTARY, 238 FINAL, 13 ARCHIVED';
END $batch$;
COMMIT;
